package vn.vinhkhang.warehouse;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.ResponseEntity;import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api") public class BulkActions{
 private final Api core;private final Operations operations;private final VehicleReceipts receipts;
 public BulkActions(Api core,Operations operations,VehicleReceipts receipts){this.core=core;this.operations=operations;this.receipts=receipts;}
 @PostMapping("/bulk-delete/{entity}") @Transactional public Map<String,Integer> remove(@RequestHeader(value="Authorization",required=false) String t,@PathVariable String entity,@RequestBody Map<String,Object> m){core.user(t,true);if(!Set.of("parts","stock","reports","suppliers","models","documents","bom","production","vehicles","shipments","receipts","audit","users").contains(entity))throw new Api.Problem(404,"Mục này không hỗ trợ xóa nhiều dòng");String reason=core.str(m,"reason");Object raw=m.get("ids");if(!(raw instanceof List<?> list)||list.isEmpty()||list.size()>1000)throw new Api.Problem(400,"Chọn từ 1 đến 1000 dòng");Set<Long> ids=new TreeSet<>();for(Object v:list){try{long id=Long.parseLong(Objects.toString(v));if(id<=0||!ids.add(id))throw new NumberFormatException();}catch(NumberFormatException e){throw new Api.Problem(400,"Danh sách dòng không hợp lệ hoặc bị trùng");}}String target=entity.equals("reports")?"stock":entity;for(long id:ids){try{if(target.equals("receipts"))receipts.remove(t,id,Map.of("reason",reason));else operations.delete(t,target,id,Map.of("reason",reason));}catch(Api.Problem e){throw new Api.Problem(e.status,"Không xóa được dòng #"+id+": "+e.getMessage()+". Chưa xóa dòng nào trong lần này.");}}return Map.of("count",ids.size());}
 @ExceptionHandler(Api.Problem.class) ResponseEntity<?> problem(Api.Problem e){return ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
}
